    def get_list(self, params: dict):
        ret_list = []

        if params['t'] == 1:
            resp = auto_request(url=params['url'], headers=HEADERS, cookies=COOKIES)
        else:
            resp = auto_request(url=params['url'], headers=HEADERS, cookies=COOKIES, json=params['data'])

        if 400 <= resp.status_code <= 599:
            return ret_list

        soup = BeautifulSoup(resp.text, "html.parser")

        if params['t'] == 1:
            wrap = soup.select_one('div.channel_list > ul')
            rows = wrap.select('li') if wrap else []
            for row in rows:
                a_tag = row.select_one('a')
                url = urljoin(params['url'], a_tag.get('href'))
                if not is_same_origin_url(url, params['url']):
                    continue

                title = a_tag.get_text(strip=True)
                pubTime = row.select_one('span').get_text(strip=True)
                ret_list.append({'url': url, 'title': title, 'pubTime': pubTime})
        if params['t'] == 2:
            wrap = soup.select_one('ul')
            rows = wrap.select('li') if wrap else []
            for row in rows:
                a_tag = row.select_one('a')
                url = urljoin("https://www.weidong.gov.cn", a_tag.get('href'))

                title = a_tag.get_text(strip=True)
                pubTime = row.select_one('span').get_text(strip=True)
                ret_list.append({'url': url, 'title': title, 'pubTime': pubTime})

        return ret_list

    def get_content(self, params: dict):
        resp = auto_request(url=params['url'], headers=HEADERS, cookies=COOKIES)
        if 400 <= resp.status_code <= 599:
            return None

        soup = BeautifulSoup(resp.text, "html.parser")
        content = soup.select_one('div.cont')
        content = handle_str.completion_url(str(content), params['url'])

        return {"title": params['title'], "pubTime": params['pubTime'], "url": params['url'], "content": content}


